 def test_public_allowed_proposal_only(self): self.assertEqual(self.a.answer('p','analyst-alice','public','Find',{'name':'lookup_public','query':'x'}).outcome,'tool-not-executed')
 def test_private_denied(self): self.assertEqual(self.a.answer('v','analyst-alice','private','Find',{'name':'lookup_public','query':'x'}).outcome,'document-not-public')
 def test_bad_nested(self): self.assertEqual(self.a.answer('b','analyst-alice','badnested','Read').outcome,'malformed-input-rejected')
 def test_bad_name_and_extra(self):
  self.assertEqual(self.a.answer('x','analyst-alice','public','Find',{'name':[],'query':'x'}).outcome,'malformed-input-rejected'); self.assertEqual(self.a.answer('y','analyst-alice','public','Find',{'name':'lookup_public','query':'x','identity':'analyst-bob'}).outcome,'malformed-input-rejected')
 def test_stop_and_reconcile(self):
  self.a.side_effect_state='unexpected-change'; self.assertEqual(self.a.answer('s','analyst-alice','public','Answer').outcome,'stop-and-recover'); self.assertEqual(self.a.answer('z','analyst-alice','public','Answer').outcome,'isolated-stop'); self.assertFalse(self.a.reconcile('wrong')); self.assertTrue(self.a.reconcile('confirmed-synthetic-state-reconciled'))
